// dump a chain of two-attribute tuples starting at addr
static void dumpChain(Buffer *buf, unsigned int addr, const char *label)
{
	cout << "CHAIN " << label << " @" << addr << endl;
	int n = 0, blocks = 0;
	while (addr != 0) {
		unsigned char *blk = readBlockFromDisk(addr, buf);
		if (!blk) { cout << "  MISSING BLOCK " << addr << endl; return; }
		Relation t[TUPLE_PER_BLK];
		readTuplesFromBlock(blk, t);
		unsigned int next;
		memcpy(&next, blk + buf->blkSize - PTR_SIZE, PTR_SIZE);
		cout << "  blk " << addr << ":";
		for (int i = 0; i < TUPLE_PER_BLK; i++) {
			if (t[i].attr1 == 0) continue;
			cout << " (" << t[i].attr1 << "," << t[i].attr2 << ")";
			n++;
		}
		cout << " next=" << next << endl;
		freeBlockInBuffer(blk, buf);
		blocks++;
		addr = next;
		if (blocks > 200) { cout << "  RUNAWAY CHAIN" << endl; break; }
	}
	cout << "  tuples=" << n << " blocks=" << blocks << endl;
}

