static string trim(string s)
{
	size_t b = s.find_first_not_of(" \t");
	if (b == string::npos) return "";
	size_t e = s.find_last_not_of(" \t");
	return s.substr(b, e - b + 1);
}

// index of the ')' matching the '(' at position i
static size_t matchParen(const string &s, size_t i)
{
	int depth = 0;
	for (size_t k = i; k < s.size(); k++) {
		if (s[k] == '(') depth++;
		else if (s[k] == ')') { depth--; if (depth == 0) return k; }
	}
	return string::npos;
}

void parseQuery(TreeNode *root, string query)
{
	query = trim(query);
	if (query.empty()) return;
	// strip one layer of fully-enclosing parentheses
	while (query[0] == '(' && matchParen(query, 0) == query.size() - 1) {
		query = trim(query.substr(1, query.size() - 2));
	}
	if (query.compare(0, 6, "SELECT") == 0 || query.compare(0, 10, "PROJECTION") == 0) {
		string op = (query[0] == 'S') ? "SELECT" : "PROJECTION";
		size_t lb = query.find('['), rb = query.find(']');
		string extra = trim(query.substr(lb + 1, rb - lb - 1));
		size_t lp = query.find('(', rb);
		size_t rp = matchParen(query, lp);
		root->left = new TreeNode(op, extra);
		parseQuery(root->left, query.substr(lp + 1, rp - lp - 1));
		return;
	}
	// top-level JOIN?
	int depth = 0;
	for (size_t k = 0; k + 4 <= query.size(); k++) {
		if (query[k] == '(') depth++;
		else if (query[k] == ')') depth--;
		else if (depth == 0 && query.compare(k, 4, "JOIN") == 0) {
			TreeNode *join = new TreeNode("JOIN");
			TreeNode l, r;
			parseQuery(&l, query.substr(0, k));
			parseQuery(&r, query.substr(k + 4));
			join->left = l.left;
			join->right = r.left;
			root->left = join;
			return;
		}
	}
	root->left = new TreeNode("LEAF", query); // relation name
}

static vector<string> splitConds(const string &cond)
{
	vector<string> out;
	size_t start = 0;
	for (size_t k = 0; k <= cond.size(); k++) {
		if (k == cond.size() || cond[k] == '&') {
			string p = trim(cond.substr(start, k - start));
			if (!p.empty()) out.push_back(p);
			start = k + 1;
		}
	}
	return out;
}

static string attrOf(const string &pred)
{
	size_t k = pred.find_first_of("=<>!");
	return trim(pred.substr(0, k));
}

static void collectLeaves(TreeNode *n, vector<string> &rels)
{
	if (n == NULL) return;
	if (n->type == "LEAF") rels.push_back(n->info);
	collectLeaves(n->left, rels);
	collectLeaves(n->right, rels);
}

// no catalog: an attribute belongs to a relation when their initials agree
static bool belongs(const string &attr, const vector<string> &rels)
{
	for (size_t i = 0; i < rels.size(); i++)
		if (!rels[i].empty() && !attr.empty() && rels[i][0] == attr[0]) return true;
	return false;
}

static bool inList(const string &attr, const string &list)
{
	vector<string> attrs;
	size_t start = 0;
	for (size_t k = 0; k <= list.size(); k++)
		if (k == list.size() || list[k] == ',') { attrs.push_back(trim(list.substr(start, k - start))); start = k + 1; }
	for (size_t i = 0; i < attrs.size(); i++) if (attrs[i] == attr) return true;
	return false;
}

static TreeNode *wrap(TreeNode *node, const vector<string> &preds)
{
	for (int i = (int)preds.size() - 1; i >= 0; i--) {
		TreeNode *s = new TreeNode("SELECT", preds[i]);
		s->left = node;
		node = s;
	}
	return node;
}

TreeNode *optimizeQuery(TreeNode *root, vector<string> info)
{
	if (root == NULL) return NULL;
	if (root->type == "SELECT") {
		vector<string> conds = splitConds(root->info);
		info.insert(info.end(), conds.begin(), conds.end());
		return optimizeQuery(root->left, info);
	}
	if (root->type == "PROJECTION") {
		vector<string> down, stay;
		for (size_t i = 0; i < info.size(); i++)
			(inList(attrOf(info[i]), root->info) ? down : stay).push_back(info[i]);
		root->left = optimizeQuery(root->left, down);
		return wrap(root, stay);
	}
	if (root->type == "JOIN") {
		vector<string> lrel, rrel, li, ri, stay;
		collectLeaves(root->left, lrel);
		collectLeaves(root->right, rrel);
		for (size_t i = 0; i < info.size(); i++) {
			string a = attrOf(info[i]);
			if (belongs(a, lrel)) li.push_back(info[i]);
			else if (belongs(a, rrel)) ri.push_back(info[i]);
			else stay.push_back(info[i]);
		}
		root->left = optimizeQuery(root->left, li);
		root->right = optimizeQuery(root->right, ri);
		return wrap(root, stay);
	}
	return wrap(root, info); // LEAF
}
